INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (72, 7, 2, 'L2 中级', '能独立在一台干净的服务器上部署完整的 MES 运行环境：数据库、应用服务、反向代理、定时任务、备份', 22, '["能写 Shell 脚本完成批量操作，并配置 cron 定时任务","能通过日志定位服务启动失败与运行报错的原因","能配置 Nginx 反向代理、静态资源服务和 HTTPS 证书","能部署数据库并建立可验证的自动备份与恢复流程","能用 Docker 打包并运行一个应用"]', '[{"title":"Shell 脚本与定时任务","desc":"讲脚本的变量、条件、循环、函数、参数传递和退出码，够写运维脚本就行。用三个实用脚本做练习：数据库备份脚本、日志清理脚本、服务健康检查脚本。再讲 crontab 的时间表达式与常见踩坑（环境变量缺失、路径问题）。面向要把重复操作自动化的人。学完能写出可靠的定时运维脚本。"},{"title":"日志排查与系统诊断","desc":"讲日志在哪（应用日志、systemd journal、系统日志）、怎么按时间和关键字定位、怎么关联多个服务的日志找因果。再讲系统层诊断：CPU 高查什么、内存满查什么、磁盘满查什么、端口占用怎么查。面向接到「系统挂了」电话的人。学完能按流程快速定位故障。"},{"title":"Nginx 反向代理与站点部署","desc":"讲 Nginx 的配置结构、反向代理到后端服务、静态文件服务、路径重写、跨域头、上传大小限制、HTTPS 证书配置。讲前后端分离项目部署时最常遇到的路由 404 问题成因。面向要部署 Web 应用的人。学完能独立完成一个前后端项目的上线配置。"},{"title":"数据库部署、备份与恢复","desc":"讲数据库的安装、初始化、字符集与时区配置、远程访问授权、连接数调整。重点讲备份：全量与增量、备份脚本、异地存放、以及最关键的一条——定期做恢复演练，没验证过的备份等于没有。面向对客户数据负责的人。学完能建立一套可靠的备份恢复机制。"},{"title":"Docker 基础与容器化部署","desc":"讲镜像与容器的关系、Dockerfile 编写、端口与目录映射、环境变量注入、compose 编排多个服务。讲容器化在 MES 交付中的实际好处：环境一致、快速重装、版本回滚。也讲它在工厂离线环境下的限制。面向要标准化交付流程的人。学完能把一套系统打包成可一键部署的容器组。"}]', 2);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (73, 7, 3, 'L3 高级', '能为一个工厂设计服务器与部署架构，建立监控告警和高可用保障，对系统长期稳定运行负责', 26, '["能根据用户数、数据量和并发场景给出服务器配置与存储规划的量化建议","能设计高可用方案并说明每一处单点故障的应对措施","能搭建监控告警体系，在用户投诉之前发现问题","能完成服务器安全加固并建立补丁与变更管理流程"]', '[{"title":"服务器选型与容量规划","desc":"教怎么把业务量换算成硬件需求：并发用户数、日报工条数、数据保留年限、看板刷新频率，分别对应 CPU、内存、磁盘 IO 和存储容量。讲物理机、虚拟机、云主机在工厂场景的取舍（很多工厂坚持数据不出厂）。面向要出部署方案的人。学完能给出带计算过程的配置建议。"},{"title":"高可用与容灾设计","desc":"逐个消灭单点：应用双节点加负载均衡、数据库主从与故障切换、存储冗余、断电保护。讲 MES 特有的降级要求——系统挂了产线不能停，必须有纸单应急流程。讲 RTO 与 RPO 怎么和客户谈。面向对可用性承诺负责的人。学完能设计分级的容灾方案。"},{"title":"监控告警体系搭建","desc":"讲监控该看什么：主机资源、服务存活、接口响应时间、数据库慢查询、业务指标异常（比如某产线两小时没报工）。讲告警怎么配才不会被忽略（分级、去重、静默期）。介绍 Prometheus 与 Zabbix 两条路线的选择。面向运维期负责人。学完能建立一套有效的监控体系。"},{"title":"安全加固与补丁管理","desc":"讲服务器基线加固：关闭无用端口与服务、禁用密码登录、限制 sudo、配置防火墙、日志审计。讲工厂环境下补丁管理的现实矛盾——必须打补丁但不能随便重启，给出停机窗口与灰度策略。面向承担合规与安全责任的人。学完能通过一次基本的安全检查。"},{"title":"边缘服务器与车间部署实战","desc":"讲把服务器放进车间的现实问题：温度、粉尘、供电不稳、无人值守。讲边缘节点与中心机房的数据同步、断网期间本地自治、远程运维通道。讲机柜选型与 UPS 配置。面向做多厂区或多车间部署的人。学完能设计一套适应工厂物理环境的部署方案。"}]', 3);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (81, 8, 1, 'L1 入门', '能看懂现场的各类标签，说出它用的是什么码制、编码里每一段代表什么、扫出来的数据进了系统哪张表', 10, '["能说清条码在制造业解决的三个核心问题：防错、效率、追溯","能识别 Code128、EAN、QR、DataMatrix 四种常见码制及其适用场景","能解释 SN 码与批次号的区别，说明什么产品该用哪种","能说清扫码枪的工作方式（键盘口模拟输入）以及它对系统设计的影响"]', '[{"title":"自动识别为什么是制造业刚需","desc":"从手工抄写的错误率讲起：手输料号出错、抄错工单号、漏记批次，这些错误在追溯时会变成查不到。讲扫码带来的三重收益——防错、提速、留痕。讲一个召回事件里有无追溯数据的成本差距。面向要向客户论证投入必要性的人。学完能讲清这笔投入的回报在哪。"},{"title":"一维码码制：Code128 与 EAN","desc":"讲一维码的结构（起始符、数据区、校验位、终止符）、Code128 的三个字符集、EAN13 的商品码规则、Code39 的局限。讲条码宽窄比、放大系数、静区对扫描成功率的影响。面向要设计标签的人。学完能选对码制并避免印出来扫不动的标签。"},{"title":"二维码：QR 与 DataMatrix","desc":"讲二维码相比一维码的容量优势和纠错能力等级。重点讲 DataMatrix 在工业场景的优势：小尺寸、可激光直刻在金属件上、部分损伤仍可读。讲汽车与电子行业为什么普遍用它。面向做零部件追溯的人。学完能为不同载体选择合适的二维码方案。"},{"title":"SN 与批次编码规则设计","desc":"讲两种身份粒度的选择依据：高价值、需单件追溯用 SN；大批量、成本敏感用批次。讲编码规则设计原则——含义段与流水段分离、长度固定、避免易混字符、预留扩展位。讲编码规则改不动的痛（已经印出去几十万张标签）。面向项目初期做规则设计的人。学完能产出一份经得起用几年的编码规范。"},{"title":"扫码枪原理与选型","desc":"讲激光式与影像式的差异、有线键盘口与无线通讯的取舍、扫码枪作为键盘输入对软件的影响（后缀回车、输入焦点、防止误录）。讲工业环境下的选型要点：抗摔、景深、暗光识别。面向要配现场硬件的人。学完能给出带型号的扫码设备选型建议。"}]', 1);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (82, 8, 2, 'L2 中级', '能独立落地一个车间的扫码作业方案：设计标签、部署打印、配置 PDA 作业流程、完成防错校验', 20, '["能用标签设计软件做出符合规范的标签模板，并对接数据源批量打印","能部署打印机与打印服务，解决多工位共享打印和打印异常的问题","能根据现场作业动线设计 PDA 扫码流程，控制每个动作的扫码次数","能设计扫码防错规则（校验位、格式校验、业务合法性校验）并处理扫错时的提示与阻断"]', '[{"title":"标签设计与 ZPL 打印指令","desc":"讲标签设计软件的模板制作、变量绑定、条码对象设置。再讲 ZPL 指令的基本结构，让人能不依赖设计软件直接从程序生成标签。讲打印精度与条码尺寸的匹配关系。面向要做批量打印功能的人。学完能实现从系统一键打印规范标签。"},{"title":"打印机部署与打印服务","desc":"讲热敏与热转印的区别与耗材选择、网络打印机的部署、多工位共享打印的队列管理、打印任务失败的重打机制。讲 Web 系统调用本地打印机的几种技术路线与各自限制。面向要解决打印落地问题的人。学完能设计一套稳定的现场打印方案。"},{"title":"PDA 与手持终端作业设计","desc":"讲 PDA 选型（安卓工业机与消费机的差异、电池续航、跌落等级），重点讲作业流程设计：一次作业扫几次码、扫码顺序、异常时怎么退出、离线时能不能干活。讲界面为什么要大字体大按钮少输入。面向做现场作业系统的人。学完能设计出工人愿意用的扫码流程。"},{"title":"RFID 原理、频段与适用场景","desc":"讲 RFID 相比条码的优势（批量读、不需视线、可重复写）和劣势（成本、金属液体干扰、读取范围不可控导致误读）。讲低频、高频、超高频三个频段的特性与典型应用。讲什么场景值得上 RFID，什么场景是浪费钱。面向做技术选型的人。学完能给出有依据的条码与 RFID 取舍建议。"},{"title":"扫码防错与校验设计","desc":"讲三层校验：格式校验（长度、字符集、校验位）、存在性校验（系统里有没有这个码）、业务合法性校验（这个料能不能上这个工位、这个 SN 是不是已经过站）。讲错误提示要让工人一眼看懂该怎么办。讲强制阻断与允许放行的边界。面向做防错项目的人。学完能设计一套真正拦得住错误的校验规则。"}]', 2);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (83, 8, 3, 'L3 高级', '能为一个集团或多工厂场景设计统一的编码与自动识别体系，并打通从扫码到完整追溯链的落地', 24, '["能设计全厂统一的编码体系，覆盖物料、产品、容器、工位、人员、模具","能规划 RFID 读写点位并评估现场干扰因素与读取可靠性","能打通正向与反向追溯链路，做到从成品 SN 查到所有上料批次，反之亦然","能对接客户或供应商的外部条码标准，处理标签格式与数据交换要求"]', '[{"title":"全厂统一编码体系设计","desc":"讲编码不只是产品编码：物料、成品 SN、周转箱、托盘、工位、员工工牌、模具、刀具都需要身份。讲统一编码委员会的必要性、编码申请与变更流程、跨工厂的段位分配。讲各车间各自编码导致集团无法汇总的真实困境。面向集团级数字化负责人。学完能主导编制一份企业编码标准。"},{"title":"RFID 项目实施与点位规划","desc":"讲 RFID 项目为什么容易翻车：读取率不达标、读到隔壁通道的标签、金属托盘屏蔽信号。讲读写器与天线的布置、功率调节、屏蔽处理、现场读取率测试方法。讲上线前必须做的实地验证。面向要交付 RFID 项目的人。学完能设计并验证一套达标的读取方案。"},{"title":"追溯链路设计与打通","desc":"讲追溯的数据模型：每一次上料、每一道工序、每一次检验都要把物料批次与产品 SN 绑定起来。讲正向追溯（这批料流向了哪些成品）与反向追溯（这台成品用了哪些料）的查询设计。讲拆解、返工、替代料这些破坏链路的场景怎么处理。面向做追溯项目的架构者。学完能设计一套不断链的追溯数据结构。"},{"title":"扫码性能与异常流程设计","desc":"讲高节拍产线上扫码的性能要求（响应必须在几百毫秒内否则拖慢节拍）、后台校验的异步化设计、网络抖动时的本地缓存。讲异常流程：标签破损怎么补、扫错了怎么撤销、系统故障时怎么手工登记并事后补录。面向对产线节拍负责的人。学完能设计既严格又不卡生产的扫码方案。"},{"title":"外部条码标准与客户对接","desc":"讲汽车行业 VDA 与 AIAG 标签标准、电子行业的常见要求、客户指定标签格式时的应对。讲 ASN 发货通知与条码数据交换、供应商来料标签的解析入库。讲不符合客户标签标准会被拒收的现实压力。面向做汽车电子等供应链上游的企业。学完能按客户标准输出合规标签。"}]', 3);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (91, 9, 1, 'L1 入门', '能独立组织一次需求调研会议，产出结构清晰的会议纪要和需求确认单，并让客户签字', 10, '["能说清一个实施项目的完整阶段划分，以及每个阶段谁负责什么、产出什么","能设计调研提纲并在会议中把客户的口头描述追问成可记录的具体流程","能写出让三个月后的人也看得懂的会议纪要，含决议、待办、责任人、时限","能编制需求确认单，把口头承诺变成书面依据"]', '[{"title":"实施项目全景：阶段、角色与交付物","desc":"讲一个典型实施项目从售前到验收的完整阶段（立项、调研、设计、配置开发、测试、上线、验收、运维移交），每个阶段的输入输出和时长占比。讲项目里的六种角色（甲方发起人、甲方关键用户、乙方项目经理、实施顾问、开发、运维）各自的诉求和冲突点。面向第一次进项目组、不知道自己该干什么的新人。学完能说清自己在项目中的位置和交付责任。"},{"title":"项目立项与范围界定","desc":"讲立项阶段必须钉死的四件事：目标、范围、时间、责任人。重点讲范围界定的写法——不只写「做什么」，更要写「不做什么」，因为后期扯皮全在这里。讲项目章程的标准结构和边界条款的措辞。面向要避免项目无限膨胀的实施人员。学完能写出一份边界清楚、后期扯得清的立项文件。"},{"title":"需求调研：怎么问出真实流程","desc":"教调研的提问方法：先问「现在怎么做」再问「想怎么做」，先看现场表单再听口头描述，让客户演示一遍而不是复述一遍。讲怎么处理三种典型情况——客户说的是理想流程不是实际流程、不同部门说法互相打架、关键用户不愿配合。给出可复用的调研提纲模板。面向要独立面对客户的实施人员。学完能带回一份基于事实而非转述的需求记录。"},{"title":"会议组织与纪要撰写","desc":"讲会前准备（议题、参会人、资料预发）、会中控场（跑题怎么拉回、争执怎么收口、沉默怎么破）、会后闭环（纪要发送、确认回复、待办跟踪）。重点讲纪要的写法：结论先行、决议与待办分开、每条待办带责任人和时限、有争议的点如实记录不美化。面向要主持客户会议的人。学完能独立开完一场有结论的会并留下可追溯的记录。"},{"title":"需求确认单与变更起点","desc":"讲为什么口头确认在项目里等于没确认。讲需求确认单的构成：需求描述、业务价值、实现方式、影响范围、工作量、双方签字。讲签字之后再提的需求就进变更流程，这条线不划清后期一定失控。给出确认单模板与签字流程。面向要保护项目边界的实施人员。学完能把每一次需求沟通固化成有法律和商务效力的文件。"}]', 1);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (92, 9, 2, 'L2 中级', '能独立编制并执行一个中小型项目的实施计划，组织完 UAT 与上线切换，拿到客户验收签字', 18, '["能把业务蓝图拆解成带依赖关系和里程碑的可执行计划，并识别关键路径","能组织关键用户完成 UAT，设计测试用例、跟踪缺陷并判断哪些缺陷可以带上线","能编制上线切换方案，安排好数据准备、时点选择、人员值守和回退条件","能主导验收会议，用事实和数据把客户从「感觉还有问题」引导到签字"]', '[{"title":"业务蓝图与方案设计文档","desc":"讲蓝图文档的标准结构：组织架构、业务流程图、单据设计、权限矩阵、报表清单、集成清单、遗留问题。讲蓝图评审会怎么开才能让客户真的看懂并敢签字，而不是碍于面子点头。讲蓝图与后续配置开发的对应关系。面向要独立产出设计文档的实施顾问。学完能写出一份能过评审、能指导开发的蓝图。"},{"title":"实施计划编制与里程碑管理","desc":"教怎么把蓝图拆成任务：任务分解、工时估算、依赖关系、关键路径识别、缓冲预留。讲里程碑该怎么设（必须是可客观判定的事件，不能是「基本完成」这种描述）。讲进度偏差的三种应对：加人、砍范围、延期，各自的代价。面向要对交付日期负责的人。学完能编出一份经得起推敲的计划并按周跟踪。"},{"title":"UAT 组织与缺陷跟踪","desc":"讲用户验收测试为什么不能让实施自己测：必须由关键用户按真实业务场景走。讲测试用例设计（覆盖主流程、异常流程、边界数据）、测试数据准备、缺陷分级（阻断/严重/一般/建议）、缺陷跟踪表的字段与流转。讲哪些缺陷必须修完才能上线、哪些可以带上线后处理。面向组织测试的项目负责人。学完能跑完一轮有效的 UAT 并输出可判定的结论。"},{"title":"上线切换与并行运行组织","desc":"讲上线不是技术动作而是组织动作：切换时点选（通常是月末盘点后或长假期间）、数据冻结与截止、人员排班值守、异常上报通道、老流程什么时候停。讲并行运行的成本与止损条件。讲回退触发条件必须提前和客户约定，不能到时候临场吵。面向要带队上线的人。学完能编制一份逐小时的切换作业表。"},{"title":"项目验收与收尾","desc":"讲验收卡壳的常见原因：验收标准从没写清楚、客户拿运维期问题当交付缺陷、关键用户离职换人重来。讲验收标准怎么在立项时就写死、验收会怎么用运行数据说话、遗留问题清单怎么和二期需求划开。讲文档移交与运维交接的清单。面向要把项目收干净的负责人。学完能推动一次不拖泥带水的验收。"}]', 2);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (93, 9, 3, 'L3 高级', '能同时管理多个项目的资源与风险，控住范围蔓延，并把项目经验沉淀成团队可复用的方法', 22, '["能在多项目并行时做资源调度与优先级取舍，说清每次取舍牺牲了什么","能建立风险清单并对高概率高影响项做出前置应对，而不是等风险发生再救火","能用变更流程把范围蔓延转成商务议题，该收费的收费、该拒绝的拒绝","能经营客户关系并在交付过程中识别出二期机会","能主持项目复盘，把个人经验转成团队可执行的模板与检查清单"]', '[{"title":"多项目并行与资源调度","desc":"讲一个人同时盯三个项目时的现实困境：三个客户都说自己最急、关键顾问被抢、出差排期打架。讲优先级判定依据（合同节点、回款条件、客户战略价值、风险敞口）、资源冲突的公开化处理、进度看板的建立。面向开始带多个项目的负责人。学完能给出有依据的排期而不是被客户嗓门大小牵着走。"},{"title":"风险识别与前置应对","desc":"讲实施项目的高频风险：关键用户离职、甲方一把手换人、主数据准备远超预期、集成方接口迟迟不给、验收标准模糊。每类给出识别信号、发生概率、影响程度和前置动作。讲风险清单该在周会上过而不是躺在文档里。面向要对项目结果负责的人。学完能建立并持续维护一份活的风险清单。"},{"title":"变更管理与范围控制","desc":"讲范围蔓延的真实形态：不是一次大改，而是几十次「这个小功能顺手加一下」。讲变更流程的四步（提出、评估、商务确认、执行）、工作量评估的说法、免费与收费的分界线怎么和客户谈。讲拒绝需求时怎么给替代方案而不是硬顶。面向要保住项目利润的负责人。学完能把变更从人情问题变成流程问题。"},{"title":"客户关系经营与二期挖掘","desc":"讲交付期就是最好的销售期：客户在这段时间对你的信任度最高。讲怎么在日常沟通里识别未被满足的诉求、怎么把客户内部的推动者变成盟友、怎么处理与客户 IT 部门和业务部门的双线关系。讲一期做砸了没有二期这个基本事实。面向承担商务指标的项目经理。学完能在交付的同时为二期铺路。"},{"title":"项目复盘与方法沉淀","desc":"讲复盘不是追责会：结构是目标回顾、结果对比、原因分析、经验提炼。讲怎么把「这次踩的坑」转成下次能用的检查清单、模板、配置基线。讲团队知识沉淀失败的常见原因——文档写了没人看，解法是把经验固化进流程和模板而不是写成文章。面向要带团队的人。学完能主持一次产出可复用资产的复盘。"}]', 3);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (101, 10, 1, 'L1 入门', '能读懂一段已有的业务代码，说清它在做什么，并在带指导的情况下改对一处小逻辑', 16, '["能把一条业务规则拆成变量、判断和循环，写成可执行的伪代码","能说清常用数据类型的差异，理解为什么金额不能用浮点数存","能用条件、循环和异常处理写出一段带输入校验的完整逻辑","能用调试器打断点、单步执行、查看变量，靠自己搞清一段陌生代码的执行路径"]', '[{"title":"编程思维：把业务规则变成可执行逻辑","desc":"不讲语法，讲思维方式：怎么把「同一工单同一工序不允许重复报工，但返工除外」这种业务口语拆成计算机能判断的条件组合。讲边界情况的枚举习惯（空值、零、超量、重复提交）。用三条真实的 MES 业务规则做拆解练习。面向没有编程背景的实施人员。学完能把需求描述转成结构清晰的逻辑步骤，这一步做对了写代码只是翻译。"},{"title":"数据类型、变量与运算","desc":"讲整数、浮点、字符串、布尔、日期时间、空值各自的存储特点与坑。重点讲工业场景的三个高频问题：金额和数量为什么要用定点数、日期时区在跨系统对接时怎么错、空值参与运算的结果。讲类型转换的隐式陷阱。面向要处理生产数据的开发者。学完能选对数据类型，避免上线后才发现的精度和时区事故。"},{"title":"流程控制：条件、循环与异常","desc":"讲 if / switch / for / while 的写法与选用，重点讲嵌套过深导致的可读性崩溃和怎么用提前返回改写。讲异常处理的正确姿势：捕获具体异常而不是全捕获、不要吞掉错误、日志要带上下文。用一个批量导入物料并逐条校验的场景贯穿。面向刚开始写代码的人。学完能写出出错时能定位原因的代码。"},{"title":"函数、模块与代码组织","desc":"讲为什么要把代码拆成函数：复用、可测、可读。讲参数与返回值设计、职责单一原则、命名规范。讲二开场景里最常见的坏味道——一个几百行的方法把校验、计算、写库、发通知全干了，改一处炸一片。面向要写出别人能接手的代码的人。学完能把一段面条代码重构成分层清晰的结构。"},{"title":"读懂别人的代码：调试与断点","desc":"讲接手陌生代码的方法：先找入口、再顺调用链、用断点验证假设而不是靠猜。讲调试器的核心操作（断点、条件断点、单步进入与跳过、变量监视、调用栈）。讲加日志排查与断点调试各自的适用场景（生产环境只能靠日志）。面向要维护别人代码的二开人员。学完能独立搞清一个陌生功能的执行路径。"}]', 1);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (102, 10, 2, 'L2 中级', '能独立完成一个定制功能的开发与自测：写业务逻辑、读写数据库、对接接口、出报表，交付后无重大缺陷', 30, '["能用 C# 或 Java 任一后端语言独立搭建工程并完成一个完整功能模块","能通过 ORM 或原生方式访问数据库，正确处理事务与连接释放","能开发并对接 REST 接口，处理认证、超时、重试和幂等","能完成定制报表与表单的二次开发，把取数逻辑与展示层分开","能给核心逻辑写单元测试，并通过日志在测试环境自主定位问题"]', '[{"title":"后端语言实操：C# 与 Java 二选一","desc":"讲两条技术栈在国内 MES 领域的分布（C# 在传统 MES 厂商占比高，Java 在新平台和大型集成商更多），给出选择建议。然后按选定语言讲工程结构、依赖管理、面向对象的类与接口、集合与泛型的日常用法。面向确定要走开发方向的人。学完能独立搭起一个能跑的后端工程并实现基本业务类。"},{"title":"数据库访问与事务控制","desc":"讲代码怎么连数据库：连接字符串与连接池、参数化查询防注入、ORM 与手写 SQL 的取舍（MES 复杂取数场景往往手写更可控）。重点讲事务：什么操作必须放一个事务里、事务边界划在哪一层、长事务锁表导致产线卡住的真实事故。面向要写业务写库逻辑的人。学完能写出不漏连接、不锁死表的数据访问代码。"},{"title":"REST 接口开发与对接","desc":"讲接口两端：作为提供方怎么设计（路径、方法、状态码、错误结构、版本），作为调用方怎么对接（认证方式、超时设置、重试策略、断路保护）。重点讲幂等设计——网络重试导致的重复报工是集成场景的高频事故。讲接口文档和联调时的排查顺序。面向做系统集成的二开人员。学完能独立完成一次双向接口对接并处理异常。"},{"title":"报表与表单二次开发","desc":"讲 MES 二开需求里占比最高的两类活。报表部分讲取数逻辑与展示层分离、分页与导出、大数据量的响应控制。表单部分讲字段扩展、动态校验规则、审批流挂接。讲怎么做才能在产品升级后不被覆盖。面向承接日常定制需求的人。学完能高效交付这两类高频需求。"},{"title":"调试、日志与单元测试","desc":"讲三件让交付质量稳定的事：日志该记什么（入参、关键分支、异常堆栈、耗时）和不该记什么（密码、完整业务数据）；单元测试怎么给核心计算逻辑加保护网；测试环境与生产环境行为不一致时怎么查。面向想让代码上线后少被叫回来改的人。学完能建立自己的自测习惯，缺陷率明显下降。"}]', 2);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (103, 10, 3, 'L3 高级', '能设计一套支撑多客户个性化需求的二开架构，规范发布流程，并解决高并发场景下的性能问题', 28, '["能设计标准产品与客户定制的隔离方案，使定制不阻碍产品版本升级","能设计插件与扩展点机制，让新需求通过扩展而非改核心代码实现","能建立分支策略与发布流程，支持多客户多版本并行维护","能定位并解决高并发报工、批量数据处理场景下的性能与死锁问题","能主持代码审查并制定团队开发规范，识别与偿还技术债"]', '[{"title":"MES 二开架构与分层设计","desc":"讲二开最核心的架构命题：怎么让十几个客户的个性化需求共存，而不是每家拉一个分支各改各的（三年后没人敢升级）。讲标准层与定制层的隔离、配置驱动优先于代码、定制代码的存放约定。讲改核心代码的代价怎么向管理层量化。面向要做技术决策的资深开发。学完能给出一套可长期维护的二开架构方案。"},{"title":"插件机制与扩展点开发","desc":"讲扩展点的常见形态：事件钩子、策略接口、脚本引擎、自定义字段与规则引擎。讲怎么在标准流程的关键节点预埋扩展点（工单下达前、报工提交后、检验判定时），让定制需求变成注册插件而不是改主干。讲扩展点粒度太粗和太细各自的问题。面向平台型产品的开发者。学完能设计一套让实施人员也能配的扩展体系。"},{"title":"版本管理、分支策略与发布","desc":"讲多客户多版本并行的现实：客户 A 在 3.2、客户 B 在 4.0、主干在开发 4.1，一个 bug 要修三个地方。讲分支模型选择、补丁回合流程、版本号规范、发布包构建与回滚。讲生产发布的检查清单和灰度手段。面向要对发布质量负责的人。学完能建立一套不会发错版本的流程。"},{"title":"性能与并发处理","desc":"讲 MES 特有的并发场景：整条流水线同一秒集中报工、批量导入十万条数据、看板每五秒刷新一次。讲数据库锁竞争、死锁定位、批量写入优化、异步队列削峰、缓存的适用与失效策略。讲性能问题必须先测量再优化。面向要支撑高节拍产线的开发者。学完能定位并解决并发瓶颈而不是靠加机器。"},{"title":"代码审查与技术债治理","desc":"讲代码审查看什么（业务逻辑正确性、边界处理、事务与并发、日志与错误处理、可维护性），不看什么（个人风格偏好）。讲技术债的识别、记录、优先级排序和偿还时机——项目压力下技术债不可避免，关键是可见可控。讲开发规范怎么落地才不是文档躺着。面向技术负责人。学完能建立起团队的质量底线。"}]', 3);
INSERT OR REPLACE INTO career_paths (id, slug, title, tagline, salary, demand, overview, daily_work, outputs, icon, sort, status) VALUES (1, 'mes-implementation', 'MES 实施工程师', '把 MES 系统装进车间并让工人真的用起来的人', '一线城市 12-20K，二线城市 8-14K；3 年以上能独立带项目 18-30K；能带团队的项目经理 25-40K。多数岗位有出差补贴，实际到手比基本薪资高 15-25%', '需求量在五个岗位中最大。中小制造企业数字化改造仍在铺开，MES 厂商与系统集成商常年招人。门槛特点是不卡学历卡现场经验，愿意出差驻厂的人明显吃香。缺口集中在既懂业务又能查数据的复合型人选', 'MES 实施工程师是连接软件产品和车间现实的人。工作从需求调研开始，到系统配置、数据准备、用户培训、上线陪跑，再到上线后的问题处理。这个岗位的核心难点不是技术，而是要在客户老板要的报表、车间主任要的管控、一线工人怕麻烦这三种诉求之间找到能落地的方案。长期出差驻厂是常态，也是快速积累项目经验的途径。', '["驻场跟线调研，记录现场实际的工单流转、报工方式、检验节点和异常处理动作","在系统里配置产线、工位、工艺路线、BOM、检验规则，并跑通测试工单","整理客户提供的主数据，清洗后按模板导入，处理编码不规范和数据缺失","给班组长和一线工人做操作培训，编写图文操作手册并现场手把手带","上线期驻场值守，处理扫码失败、报工报错、数据对不上等现场问题"]', '["需求调研报告与业务流程现状图","系统配置清单与主数据导入文件","用户操作手册与培训记录","上线切换方案、问题跟踪表与项目验收文档"]', 'role-mes-impl', 1, 'published');
INSERT OR REPLACE INTO career_paths (id, slug, title, tagline, salary, demand, overview, daily_work, outputs, icon, sort, status) VALUES (2, 'erp-consultant', 'ERP 实施顾问', '用系统重新组织一家企业的业务流程和账务逻辑', '一线城市 15-25K，二线城市 10-18K；能独立带模块的资深顾问 25-40K；项目经理级 35-60K。财务与供应链模块的顾问普遍高于生产模块', '需求稳定但门槛高于 MES 实施。国产 ERP 厂商与代理商是主要用人方，同时大量制造企业自建 IT 团队招内部顾问。行业偏好有制造业务背景的人转岗，纯技术出身反而不占优势。资深顾问长期供不应求', 'ERP 实施顾问的工作对象是企业的业务流程和账，不是车间设备。核心能力是把客户混乱的现行流程梳理成系统能承载的标准流程，并说服客户接受必要的改变。这个岗位对沟通与业务理解的要求高于技术，需要能和财务经理、供应链总监、老板直接对话。项目周期通常比 MES 长，六个月到一年是常态，对项目管理能力要求高。这条路径完全不需要 PLC 与设备侧技能。', '["组织业务调研会议，梳理客户现行的订单、采购、库存、生产、成本流程","设计并配置组织架构、单据流、审批流、权限矩阵和会计科目对应关系","把客户需求逐条做 Fit-Gap 分析，判断标准功能能否满足，写二开需求说明","带客户做数据准备与期初建账，逐轮验证试算平衡","主持关键用户测试与上线培训，处理月结期间的账务异常"]', '["业务蓝图文档与流程设计图","Fit-Gap 差异分析清单与二开需求说明书","数据迁移方案与期初建账对账表","上线切换计划、测试用例集与项目验收报告"]', 'role-erp-consultant', 2, 'published');
INSERT OR REPLACE INTO career_paths (id, slug, title, tagline, salary, demand, overview, daily_work, outputs, icon, sort, status) VALUES (3, 'mes-dev', 'MES 实施开发（二次开发）', '标准功能不够用时，写代码把它补上的人', '一线城市 15-28K，二线城市 11-20K；能独立设计模块的资深开发 25-40K；技术负责人 35-55K。比纯实施岗位高 20-30%，但对代码能力有硬要求', '需求量仅次于 MES 实施工程师。每个 MES 产品都无法覆盖所有客户的个性化需求，二开是行业常态。用人方是 MES 厂商、集成商和大型制造企业内部 IT。特点是既要会写代码又要懂车间业务，纯程序员来了往往做不对需求，这个交集造成持续缺口', 'MES 实施开发处在实施与研发之间。工作是在标准产品之上做定制：加报表、改流程、写接口、做数据处理任务。这个岗位和纯后端开发的关键差别在于，需求不是产品经理给的规格说明，而是客户现场提出的模糊要求，需要自己转成技术方案。数据库能力的权重高于框架能力，因为大量工作是取数、算指标和对接系统。往上可以走技术负责人或架构方向。', '["把客户提出的定制需求转成技术方案，评估工作量并判断是否会影响后续升级","开发定制报表与看板，编写并优化取数逻辑","开发与 ERP、WMS、SCADA、客户自有系统的数据接口","排查线上问题：接口失败、数据不一致、查询超时、任务未执行","编写数据修正脚本与批处理任务，处理历史脏数据"]', '["定制功能的技术方案与接口文档","可上线的代码、测试用例与部署说明","数据修正脚本与执行记录","线上问题的根因分析与修复报告"]', 'role-mes-dev', 3, 'published');
INSERT OR REPLACE INTO career_paths (id, slug, title, tagline, salary, demand, overview, daily_work, outputs, icon, sort, status) VALUES (4, 'scada-engineer', 'SCADA 数采工程师', '把车间里每一台设备的数据真实地取出来的人', '一线城市 14-24K，二线城市 10-18K；能独立设计数采架构的资深工程师 22-38K。有嵌入式能力可再上浮 15-20%，因为能接下别人做不了的定制活', '需求增长最快的方向。设备联网、稼动率自动采集、能耗监测、数字孪生这些项目都需要这类人。缺口原因是它要求跨界：懂设备与电气的人往往不懂软件与数据库，懂软件的人不敢下车间碰设备。两头都通的人很少，议价空间大', 'SCADA 数采工程师负责设备侧到系统侧的整条数据链路。工作从与电气工程师确定点表开始，到选协议、配采集、验数据、做监控画面，再到处理断线、跳变、漏采等现场问题。这个岗位需要真的下车间、开配电柜、接线调试，也需要写脚本、查数据库、分析报文。它是五条路径中唯一必须掌握 PLC 高级能力的岗位，也是嵌入式选修线价值最大的地方。', '["与电气工程师协作确定点表，明确每个信号点的地址、类型、含义与量纲","配置采集链路：选通讯协议、配网关、建采集点、验证数据准确性","搭建 SCADA 监控画面与实时数据看板，配置报警规则","现场排查数采故障：数据断流、数值跳变、采集延迟、点位漂移","把设备数据对接到 MES，实现稼动率、产量、故障时长的自动统计"]', '["设备点表与地址规划文档","数采架构图与协议选型说明","SCADA 组态画面与报警配置","数据准确性验证报告与故障处理记录"]', 'role-scada', 4, 'published');
INSERT OR REPLACE INTO career_paths (id, slug, title, tagline, salary, demand, overview, daily_work, outputs, icon, sort, status) VALUES (5, 'digital-specialist', '甲方数字化专员', '在制造企业内部，替公司想清楚该上什么系统、盯着乙方把活干对', '一线城市 12-20K，二线城市 8-15K；数字化主管 18-30K；数字化经理或 IT 负责人 25-45K。稳定性高于乙方岗位，出差少，但涨薪节奏偏慢', '需求在稳步扩大。制造企业在经历几次系统上线失败后，普遍意识到必须有懂行的内部人牵头。用人方偏好有乙方实施经验的人转甲方，也接受内部业务骨干转岗。这个岗位的能力要求是宽而不是深——要能和 ERP 顾问、MES 工程师、设备厂商三方都对得上话', '甲方数字化专员站在企业内部视角，负责需求提出、供应商选型、项目监督、上线推动和长期运维协调。它和乙方岗位最大的差别是，乙方交付完就走，甲方要陪着系统过完整个生命周期，所以更在意可维护性和长期成本。这个岗位的核心难点是内部推动力：系统好不好用不完全取决于软件，更取决于业务部门配不配合。技能上要求广度覆盖 ERP、MES、SQL 和基础的识别与网络认知，不需要 PLC 深度能力。', '["收集并梳理各业务部门的系统需求，判断真伪与优先级，形成需求清单","参与供应商选型：编写需求书、组织方案评审、评估报价与实施能力","跟进项目进度，主持周例会，推动跨部门的数据准备与测试配合","自己写查询验证系统数据，独立回答老板「这个数字准不准」的追问","上线后收集用户反馈、提交变更需求、协调厂商处理问题并跟踪闭环"]', '["业务需求说明书与系统选型评估报告","项目进度跟踪表与问题风险清单","系统上线后的数据核对与运行报告","企业级的系统规划路线图与年度预算建议"]', 'role-owner-digital', 5, 'published');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (101, 1, 1, '打基础：看懂工厂和系统', '0-1 个月', '建立制造业业务语言体系，能听懂车间和客户在说什么，能看懂 MES 系统每个界面在干什么', '拿到一份陌生工厂的产品与产线介绍，能画出它的物料流与信息流草图，并说明 MES 应该在哪几个节点采集数据', '["MES 和 ERP 的区别是什么，边界怎么划","举例说明一张工单在车间里从下达到完工经过哪些环节","什么是 BOM，多层 BOM 在生产中怎么用","为什么工厂要做生产追溯，追溯需要采集哪些数据"]', '["一份自选制造业产品的物料流与信息流分析图","一份 MES 七大模块的功能与业务场景对照笔记"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (102, 1, 2, '上手：在带教下完成配置任务', '1-3 个月', '能在项目经理分配任务的前提下，独立完成模块配置、数据整理和培训执行，交付质量不需要返工', '独立完成一个车间的产线、工艺路线、BOM 与检验规则配置，跑通一张测试工单的全流程，并通过项目经理评审', '["工艺路线怎么配，工序之间的先后与并行关系怎么表达","替代料和损耗在 BOM 里怎么处理","首检、巡检、终检分别在什么时机触发，不合格品怎么流转","一次直通率怎么计算，数据从哪几张表来"]', '["一个完整车间的系统配置清单与配置说明","一份主数据导入模板与校验 SQL 脚本","一份面向一线工人的图文操作手册"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (103, 1, 3, '独立：自己扛一个项目', '3-12 个月', '能独立负责一个中小型 MES 项目从调研到上线的完整过程，对交付结果和客户满意度负责', '独立主导一个项目上线，上线后一个月内现场问题闭环率达标，客户签署验收', '["讲一个你负责的项目，需求调研阶段你怎么判断客户说的功能是不是真需求","MES 和 ERP 的接口你怎么设计，两边数据不一致怎么对账","上线当天在制品怎么处理，系统出问题怎么应急","工人抵触使用新系统，你怎么解决"]', '["一份完整的项目实施方案，含范围、计划、风险清单","一份系统集成接口规格说明书","一份上线切换方案与应急预案"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (104, 1, 4, '资深：做方案和带人', '1-3 年', '能承接复杂项目的方案设计与售前支持，能带教新人并沉淀方法论，具备向项目经理或售前顾问转型的能力', '独立完成一次售前方案汇报并中标，或同时管理两个以上项目且都按期验收', '["面对一个从没做过的行业，你怎么快速形成方案","客户预算有限但需求很多，你怎么划分一期二期","讲一次你救回来的项目，问题根因是什么","你怎么把项目经验沉淀成团队可复用的资产"]', '["一份可用于投标的整体解决方案与报价模型","一套团队可复用的实施方法论与模板库","一份新人带教计划与考核标准"]');
